use super::*;

/// Resolve the target of an ask.
///
/// Refuses a session asking ITSELF: delivering a request into the very session that is mid-turn
/// issuing it would either interrupt the caller or write into its own prompt behind its back.
///
/// The check is against the ACTUAL caller, not against the architect. Hard-coding the architect here
/// meant a director could never ask the architect anything: it was refused for being "the caller of
/// this verb" when it was the callee, which is the one direction the funnel had no lane for.
pub fn resolve_askable(id: &str, caller: &str) -> Result<crate::ResolvedSession, String> {
    let s = crate::resolve(id)?;
    if s.id == caller {
        return Err(format!(
            "'{}' cannot ask itself — the request would be delivered into the session that is \
             issuing it.",
            s.id
        ));
    }
    Ok(s)
}
